style.css:
@-moz-document domain("pekora.zip") {
/* ==== FONTS & BASE ==== */
    * {
        font-family: 'Source Sans Pro', Arial, sans-serif !important;
    }

    body {
        background-color: #e1e1e1 !important;
        color: #1c1c1c !important;
        margin: 0 !important;
        padding: 0 !important;
    }

    a {
        color: #c52f30 !important;
        text-decoration: none !important;
    }

    a:hover {
        text-decoration: underline !important;
    }

    /* ==== NAVIGATION BAR ==== */
    header, .navbar, .top-nav, .site-header, .nav-bar {
        background-color: #c52f30 !important;
        border-bottom: 2px solid #9b1c1c !important;
        color: white !important;
    }

    .navbar a, .top-nav a, .nav-bar a {
        color: white !important;
        font-weight: bold !important;
        text-transform: uppercase !important;
        padding: 10px 12px !important;
    }

    .navbar a:hover {
        background-color: #a52828 !important;
    }

    /* ==== FAKE 2017 NAVIGATION LINKS ==== */
    .fake-nav {
        background-color: #c52f30 !important;
        padding: 10px 15px;
        font-size: 15px;
        display: flex;
        gap: 12px;
    }

    .fake-nav a {
        color: white !important;
        font-weight: bold;
    }

    /* ==== BUTTONS ==== */
    button, .btn, input[type="submit"], .button {
        background-color: #c52f30 !important;
        color: white !important;
        border: none !important;
        border-radius: 4px !important;
        padding: 6px 12px !important;
    }

    button:hover, .btn:hover {
        background-color: #a52828 !important;
    }

    /* ==== PANELS / BOXES ==== */
    .panel, .card, .box, .content-box, .section, .module {
        background-color: #f5f5f5 !important;
        border: 1px solid #ccc !important;
        padding: 10px !important;
        border-radius: 4px;
    }

    /* ==== GAME THUMBNAILS / TILES ==== */
    .game-tile, .game-card, .game-thumbnail {
        background-color: white !important;
        border: 1px solid #ccc !important;
        box-shadow: none !important;
        border-radius: 4px !important;
        overflow: hidden !important;
    }

    .game-tile img, .game-thumbnail img {
        border-radius: 0 !important;
    }

    /* ==== AVATAR ==== */
    .avatar, .user-avatar, .profile-avatar {
        border: 2px solid #c52f30 !important;
        background-color: white !important;
        border-radius: 4px;
    }

    /* ==== PROFILE HEADERS ==== */
    .profile-header, .user-info, .profile-container {
        background-color: #f2f2f2 !important;
        border: 1px solid #ccc !important;
    }

    /* ==== FOOTER ==== */
    footer, .site-footer {
        background-color: #c52f30 !important;
        color: white !important;
        padding: 20px !important;
    }

    /* ==== SCROLLBAR ==== */
    ::-webkit-scrollbar {
        width: 8px;
    }

    ::-webkit-scrollbar-track {
        background: #f1f1f1;
    }

    ::-webkit-scrollbar-thumb {
        background: #c52f30;
        border-radius: 4px;
    }

    ::-webkit-scrollbar-thumb:hover {
        background: #a52a2a;
    }

    /* ==== TABS / NAV BUTTONS ==== */
    .tab, .nav-button, .menu-item {
        background-color: #c52f30 !important;
        color: white !important;
        border: none !important;
        padding: 8px 12px;
    }

    .tab:hover, .nav-button:hover {
        background-color: #a52a2a !important;
    }

    /* ==== MISC ==== */
    .alert, .notice, .warning {
        background-color: #ffefef !important;
        border-left: 4px solid #c52f30 !important;
        padding: 10px;
    }
}
